<script>
import blueprints from '../data/blueprints.json';
import { validate } from '../lib/invariants';
import { render } from '../lib/renderManifest';
import { isAllowed } from '../lib/gate';
import {
  listCloudCredentials,
  postMachineConfig,
  postCluster,
  getClusterStatus,
} from '../lib/steve';

function defaultZone(zone, provider = 'harvester') {
  return {
    zone,
    provider,
    credentialId: '',
    // --- Harvester (provider='harvester') ---
    vmNamespace:  'default',
    networkName:  'shared-k8s/fcs-backend-vm-net',
    image:        '',
    // Node-Root-Storage der Site: 'longhorn' (Default, image) oder 'ceph' (cephImage,
    // Root-PVC auf Rook-Ceph-RBD via VMImage.targetStorageClassName).
    nodeStorage:  'longhorn',
    cephImage:    '',
    // EFI-Boot pro Zone setzbar — image-/insel-abhängig (PoC-Befund: gleiches
    // Leap-Micro-Image bootete dev nur mit false, DC2 mit true; Root-Cause offen).
    // Default true (Plan-Vorgabe); für betroffene dev-Images abwählen.
    enableEfi:    true,
    // --- vSphere (provider='vsphere', z.B. HAN-Witness) ---
    vsphere: {
      datacenter: '', datastore: '', pool: '', folder: '',
      network: '', cloneFrom: '', os: 'linux',
    },
    sshUser:      'sles',
    cpu:          4,
    mem:          8,
    disk:         40,
    cpQuantity:   zone === 'b1' ? 2 : 1,
    workerCount:  1,
    etcdOnly:     false,
  };
}

export default {
  name:   'ProvisionWizard',
  layout: 'plain',

  data() {
    return {
      spec: {
        name:        'sfh-stretch-poc',
        k8sVersion:  blueprints.defaultK8sVersion,
        podCidr:     blueprints.defaultPodCidr,
        serviceCidr: blueprints.defaultServiceCidr,
        routingMode: 'tunnel',
        zones:       [defaultZone('b1'), defaultZone('b2')],
      },
      credentials:  [],
      errors:       [],
      log:          [],
      busy:         false,
      loadingCreds: true,
      isAdmin:      true,
    };
  },

  async mounted() {
    // Admin-Gate auf die Aktion (nicht auf die Nav): isAdminUser greift hier korrekt,
    // weil die management-Schemas zur Nav-Zeit geladen sind.
    this.isAdmin = isAllowed(this.$store);
    try {
      this.credentials = await listCloudCredentials(this.$store);
    } catch (e) {
      this.errors = [`Cloud-Credentials konnten nicht geladen werden: ${ e?.message || e }`];
    } finally {
      this.loadingCreds = false;
    }
  },

  methods: {
    // Credentials passend zum Provider der Zone (Harvester-Insel vs. vSphere/vCenter).
    credsForProvider(provider) {
      const want = provider === 'vsphere' ? 'vmwarevsphere' : 'harvester';
      return this.credentials.filter((c) => c.provider === want);
    },
    // Provider-Wechsel: Credential UND ALLE provider-/site-spezifischen Felder aus frischen
    // Defaults setzen, sonst wandert Alt-Zustand (Harvester: vmNamespace/networkName/image/
    // cephImage/nodeStorage/enableEfi bzw. vSphere-Block) in den neuen Provider und rendert
    // falsch (CMR-P3, Runde 2). Provider-agnostisches Sizing/Rollen (cpu/mem/disk/cp/worker/
    // etcdOnly) bleibt erhalten — nur was providerspezifisch ist, wird zurückgesetzt.
    onProviderChange(z) {
      const d = defaultZone(z.zone, z.provider);
      z.credentialId = '';
      z.sshUser      = d.sshUser;
      z.vmNamespace  = d.vmNamespace;
      z.networkName  = d.networkName;
      z.image        = d.image;
      z.nodeStorage  = d.nodeStorage;
      z.cephImage    = d.cephImage;
      z.enableEfi    = d.enableEfi;
      z.vsphere      = { ...d.vsphere };
    },
    addZone() {
      this.spec.zones.push(defaultZone(`z${ this.spec.zones.length + 1 }`));
    },
    removeZone(i) {
      this.spec.zones.splice(i, 1);
    },
    validateNow() {
      this.errors = validate(this.spec);
      return this.errors.length === 0;
    },
    push(m) {
      this.log.push(m);
    },
    previewManifest() {
      if (!this.validateNow()) {
        return;
      }
      const { machineConfigs, cluster } = render(this.spec);
      this.log = [JSON.stringify({ machineConfigs, cluster }, null, 2)];
    },
    async createCluster() {
      if (!this.isAdmin) {
        this.errors = ['Nur Platform-Admins dürfen Multi-Site-Cluster provisionieren.'];
        return;
      }
      if (!this.validateNow()) {
        return;
      }
      this.busy = true;
      this.log = [];
      try {
        const { machineConfigs, cluster } = render(this.spec);
        for (const mc of machineConfigs) {
          // postMachineConfig upsertet (POST, bei 409 PUT) -> keine stale Config.
          this.push(`Upsert ${ mc.kind } ${ mc.metadata.name } ...`);
          await postMachineConfig(this.$store, mc);
        }
        this.push(`POST Cluster ${ cluster.metadata.name } ...`);
        await postCluster(this.$store, cluster);
        this.push('Cluster-Provisioning angestoßen. Warte auf status.ready ...');
        for (let i = 0; i < 90; i++) {
          await new Promise((r) => setTimeout(r, 10000));
          const s = await getClusterStatus(this.$store, cluster.metadata.name);
          this.push(`  [${ i }] ready=${ s.ready }`);
          if (s.ready) {
            this.push('Cluster ist Ready ✅');
            break;
          }
        }
      } catch (e) {
        this.errors = [`Fehler: ${ e?.message || e }`];
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<template>
  <div class="msp">
    <header class="msp__header">
      <h1>Multi-Site Cluster Provisioner</h1>
      <p>Gestreckter RKE2-Cluster über mehrere Sites — Harvester-Inseln und/oder vSphere/vCenter (z.B. HAN-Witness), per-Zone-Credential, <code>cloud-provider-name: external</code>.</p>
    </header>

    <div
      v-if="!isAdmin"
      class="msp__notice"
    >
      Nur <strong>Platform-Admins</strong> können hier provisionieren. Vorschau/Manifest sind sichtbar, „Cluster anlegen" ist deaktiviert.
    </div>

    <div
      v-if="errors.length"
      class="msp__errors"
    >
      <strong>Bitte korrigieren:</strong>
      <ul>
        <li
          v-for="(err, i) in errors"
          :key="i"
        >
          {{ err }}
        </li>
      </ul>
    </div>

    <section class="msp__cluster">
      <label>Cluster-Name <input v-model="spec.name"></label>
      <label>Kubernetes-Version <input v-model="spec.k8sVersion"></label>
      <label>Pod-CIDR <input v-model="spec.podCidr"></label>
      <label>Service-CIDR <input v-model="spec.serviceCidr"></label>
      <label>Routing
        <select v-model="spec.routingMode">
          <option value="tunnel">tunnel (PoC)</option>
          <option value="native">native+BGP (PROD)</option>
        </select>
      </label>
    </section>

    <h2>Zonen (Sites — Harvester-Inseln + vSphere)</h2>
    <table class="msp__zones">
      <thead>
        <tr>
          <th>Zone</th><th>Provider</th><th>Cloud-Credential</th><th>sshUser</th>
          <th>vCPU</th><th>GiB</th><th>Disk</th><th>CP</th><th>Worker</th>
          <th title="Witness/Tiebreaker: reiner etcd-Voter, getaintet (keine Workloads)">etcd-only</th><th></th>
        </tr>
      </thead>
      <tbody>
        <template
          v-for="(z, i) in spec.zones"
          :key="i"
        >
          <tr>
            <td><input v-model="z.zone" size="4"></td>
            <td>
              <select
                v-model="z.provider"
                @change="onProviderChange(z)"
              >
                <option value="harvester">
                  Harvester
                </option>
                <option value="vsphere">
                  vSphere
                </option>
              </select>
            </td>
            <td>
              <select
                v-model="z.credentialId"
                :disabled="loadingCreds"
              >
                <option value="">
                  — wählen —
                </option>
                <option
                  v-for="c in credsForProvider(z.provider)"
                  :key="c.id"
                  :value="c.id"
                >
                  {{ c.name }} ({{ c.id }})
                </option>
              </select>
            </td>
            <td><input v-model="z.sshUser" size="6"></td>
            <td><input
              v-model.number="z.cpu"
              type="number"
              size="2"
            ></td>
            <td><input
              v-model.number="z.mem"
              type="number"
              size="2"
            ></td>
            <td><input
              v-model.number="z.disk"
              type="number"
              size="3"
            ></td>
            <td><input
              v-model.number="z.cpQuantity"
              type="number"
              size="2"
            ></td>
            <td><input
              v-model.number="z.workerCount"
              type="number"
              size="2"
            ></td>
            <td><input
              v-model="z.etcdOnly"
              type="checkbox"
            ></td>
            <td><button @click="removeZone(i)">
              ✕
            </button></td>
          </tr>
          <tr class="msp__detail">
            <td colspan="11">
              <template v-if="z.provider === 'vsphere'">
                <label>Datacenter <input v-model="z.vsphere.datacenter" size="14" placeholder="/HAN-DC"></label>
                <label>Datastore <input v-model="z.vsphere.datastore" size="12"></label>
                <label title="Storage-DRS-Cluster — alternativ zu Datastore (genau eines ausfüllen; datastoreCluster hat Vorrang)">Datastore-Cluster <input v-model="z.vsphere.datastoreCluster" size="12"></label>
                <label>Pool <input v-model="z.vsphere.pool" size="10"></label>
                <label>Folder <input v-model="z.vsphere.folder" size="10"></label>
                <label>Network (PortGroup) <input v-model="z.vsphere.network" size="14"></label>
                <label>Template (cloneFrom) <input v-model="z.vsphere.cloneFrom" size="16"></label>
                <label>OS <input v-model="z.vsphere.os" size="6"></label>
              </template>
              <template v-else>
                <label>VM-NS <input v-model="z.vmNamespace" size="8"></label>
                <label>Network <input v-model="z.networkName" size="20"></label>
                <label title="Node-Root-Storage der Site: Longhorn (Default) oder Ceph — Root-PVC landet dann auf Rook-Ceph-RBD (via VMImage.targetStorageClassName)">Node-Storage
                  <select v-model="z.nodeStorage">
                    <option value="longhorn">
                      Longhorn
                    </option>
                    <option value="ceph">
                      Ceph (Rook-RBD)
                    </option>
                  </select>
                </label>
                <label v-if="z.nodeStorage !== 'ceph'">Image <input v-model="z.image" size="16" placeholder="default/image-…"></label>
                <label
                  v-else
                  title="Ceph-VMImage der Site — deren spec.targetStorageClassName zeigt auf rook-ceph-harvester-…-rbd"
                >Ceph-Image <input v-model="z.cephImage" size="16" placeholder="default/cephimg-…"></label>
                <label title="EFI-Boot — image-/insel-abhängig">EFI <input v-model="z.enableEfi" type="checkbox"></label>
              </template>
            </td>
          </tr>
        </template>
      </tbody>
    </table>
    <button @click="addZone">
      + Zone
    </button>

    <div class="msp__actions">
      <button
        :disabled="busy"
        @click="previewManifest"
      >
        Manifest-Vorschau
      </button>
      <button
        class="msp__primary"
        :disabled="busy || !isAdmin"
        @click="createCluster"
      >
        {{ busy ? 'Provisioniere …' : 'Cluster anlegen' }}
      </button>
    </div>

    <pre
      v-if="log.length"
      class="msp__log"
    >{{ log.join('\n') }}</pre>
  </div>
</template>

